import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        if N == 1:
            results.append("1")
        elif N == 2:
            results.append("2 1")
        else:
            arr = []
            k = 1
            while len(arr) < N:
                for x in range(1, k + 1):
                    if len(arr) < N:
                        arr.append(x)
                    else:
                        break
                k += 1
            results.append(" ".join(map(str, arr)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
